// MinimockListCommandsInspect logs each unmet expectation
func (m *PlannerServiceMock) MinimockListCommandsInspect() {
	for _, e := range m.ListCommandsMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to PlannerServiceMock.ListCommands at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterListCommandsCounter := mm_atomic.LoadUint64(&m.afterListCommandsCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.ListCommandsMock.defaultExpectation != nil && afterListCommandsCounter < 1 {
		if m.ListCommandsMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to PlannerServiceMock.ListCommands at\n%s", m.ListCommandsMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to PlannerServiceMock.ListCommands at\n%s with params: %#v", m.ListCommandsMock.defaultExpectation.expectationOrigins.origin, *m.ListCommandsMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcListCommands != nil && afterListCommandsCounter < 1 {
		m.t.Errorf("Expected call to PlannerServiceMock.ListCommands at\n%s", m.funcListCommandsOrigin)
	}

	if !m.ListCommandsMock.invocationsDone() && afterListCommandsCounter > 0 {
		m.t.Errorf("Expected %d calls to PlannerServiceMock.ListCommands at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.ListCommandsMock.expectedInvocations), m.ListCommandsMock.expectedInvocationsOrigin, afterListCommandsCounter)
	}
}

